import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/faq.md","filePath":"zh/faq.md","lastUpdated":null}'),o={name:"zh/faq.md"};function r(l,a,n,d,h,c){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="启动报错-the-value-for-version-in-dsh-credentials-yaml-must-be-a-string" tabindex="-1">启动报错：<code>the value for &quot;version&quot; in ~/.dsh/.credentials.yaml must be a string</code> <a class="header-anchor" href="#启动报错-the-value-for-version-in-dsh-credentials-yaml-must-be-a-string" aria-label="Permalink to &quot;启动报错：`the value for &quot;version&quot; in ~/.dsh/.credentials.yaml must be a string`&quot;">​</a></h2><p>这是 dsh 内核读取凭据配置失败，不是本应用问题。原因通常是 <code>.credentials.yaml</code> <strong>顶层</strong> <code>version</code> 为数字。</p><p>修复：编辑 <code>C:\\Users\\&lt;你&gt;\\.dsh\\.credentials.yaml</code>（或对应主目录），把首行改为带引号：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span></code></pre></div><p>保存后重新启动。内部 <code>payload.version</code> 无需改动。</p><h2 id="启动后一直停留在加载转圈-进不去界面" tabindex="-1">启动后一直停留在加载转圈，进不去界面 <a class="header-anchor" href="#启动后一直停留在加载转圈-进不去界面" aria-label="Permalink to &quot;启动后一直停留在加载转圈，进不去界面&quot;">​</a></h2><p>应用通过 dsh 打印的 <code>dsh web: &lt;url&gt;</code> 解析地址。若长时间无 URL：</p><ul><li>查看「终端」视图的 dsh 输出是否有报错；</li><li>检查所选端口是否被占用（会自动上扫空闲端口）；</li><li>确认内核已安装、工作目录存在且可读。</li></ul><h2 id="按-f12-控制台没反应" tabindex="-1">按 F12 控制台没反应 <a class="header-anchor" href="#按-f12-控制台没反应" aria-label="Permalink to &quot;按 F12 控制台没反应&quot;">​</a></h2><p>控制台需要先开启<strong>开发模式</strong>：设置 → 关于 → 打开「开发模式」。默认关闭以避免误开。</p><h2 id="为什么卸载-升级要-先停止-dsh" tabindex="-1">为什么卸载 / 升级要“先停止 dsh” <a class="header-anchor" href="#为什么卸载-升级要-先停止-dsh" aria-label="Permalink to &quot;为什么卸载 / 升级要“先停止 dsh”&quot;">​</a></h2><p>Windows 下运行中的 dsh 会锁定内核模块文件，导致替换/删除失败。应用会先停止再操作；若仍有进程占用会检测并提示你先关闭相关进程。</p><h2 id="无法连接-检查更新失败" tabindex="-1">无法连接 / 检查更新失败 <a class="header-anchor" href="#无法连接-检查更新失败" aria-label="Permalink to &quot;无法连接 / 检查更新失败&quot;">​</a></h2><ul><li>检查网络，必要时在设置内把内核镜像源切到 <code>npmmirror</code> 试一次；</li><li>应用与内核更新走不同通道（GitHub / npm），若 GitHub 不可达，应用自更新可能失败而内核不受影响。</li></ul><h2 id="想同时打开多个实例" tabindex="-1">想同时打开多个实例 <a class="header-anchor" href="#想同时打开多个实例" aria-label="Permalink to &quot;想同时打开多个实例&quot;">​</a></h2><p>默认<strong>单实例</strong>：重复启动会唤起已有窗口并置前，而不是新开一个。</p><blockquote><p>注意区分「多实例」与「多窗口」：应用<strong>支持多窗口</strong>——在标签上右键「在新窗口打开」即可开出副窗口（见<a href="/zh/usage">标签页与多窗口</a>）。这是同一个应用内的多个窗口，不是同时运行多个应用实例。</p></blockquote><h2 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h2><p>若以上未解决，请带上「终端」视图的日志与版本号（应用版本、内核版本）反馈给维护者。</p>',20)])])}const m=e(o,[["render",r]]);export{p as __pageData,m as default};
